import { TASKS_RPC, } from "../rpc/channels.js";
import { handleRpc, PROTOCOL_VERSION } from "../rpc/cross-extension-rpc.js";
import { claimTask, cleanTasks, createTask, heartbeatTask, taskMutationRejectionMessage, updateTask, } from "./task-mutations.js";
/** Discriminates pi-loop's own ping replies from an external pi-tasks provider. */
export const NATIVE_TASKS_PROVIDER = "pi-loop-native";
const MIN_TASK_LEASE_MS = 60_000;
const MAX_TASK_LEASE_MS = 3_600_000;
export function registerNativeTaskRpc(options) {
    const { pi, getNativeTaskStore, isEnabled, isDetectionSettled, evaluateTaskBacklog, updateWidget, debug, } = options;
    const rpcOpts = { enabled: isEnabled, debug };
    const settledRpcOpts = {
        enabled: () => (isEnabled ? isEnabled() : true) && (isDetectionSettled ? isDetectionSettled() : true),
        debug,
    };
    function requireMutationContext() {
        const taskStore = getNativeTaskStore();
        if (!taskStore)
            throw new Error("native task store unavailable");
        return { pi, taskStore, evaluateTaskBacklog, updateWidget };
    }
    handleRpc(pi.events, TASKS_RPC.ping, () => ({ version: PROTOCOL_VERSION, provider: NATIVE_TASKS_PROVIDER }), rpcOpts);
    handleRpc(pi.events, TASKS_RPC.pending, () => ({ pending: requireMutationContext().taskStore.pendingCount() }), settledRpcOpts);
    handleRpc(pi.events, TASKS_RPC.create, async (request) => {
        if (!request.subject || !request.description) {
            throw new Error("subject and description are required");
        }
        const { entry } = await createTask(requireMutationContext(), {
            subject: request.subject,
            description: request.description,
            metadata: request.metadata,
        });
        return { id: entry.id, task: entry };
    }, settledRpcOpts);
    handleRpc(pi.events, TASKS_RPC.clean, async () => {
        const pruned = await cleanTasks(requireMutationContext());
        debug?.(`${TASKS_RPC.clean} — pruned ${pruned} completed task(s)`);
        return { pruned };
    }, settledRpcOpts);
    handleRpc(pi.events, TASKS_RPC.update, async (request) => {
        if (!request.id)
            throw new Error("id is required");
        const result = await updateTask(requireMutationContext(), {
            id: request.id,
            status: request.status,
            subject: request.subject,
            description: request.description,
            claimId: request.claimId,
        });
        if (!result.applied)
            throw new Error(taskMutationRejectionMessage(request.id, result));
        return { task: result.entry };
    }, settledRpcOpts);
    handleRpc(pi.events, TASKS_RPC.claim, async (request) => {
        const leaseMs = request.leaseMs;
        if (!request.id || !request.ownerSessionId || !request.ownerRuntimeId
            || typeof leaseMs !== "number" || !Number.isSafeInteger(leaseMs)
            || leaseMs < MIN_TASK_LEASE_MS || leaseMs > MAX_TASK_LEASE_MS) {
            throw new Error("id, ownerSessionId, ownerRuntimeId, and leaseMs between 60000 and 3600000 are required");
        }
        const claimed = await claimTask(requireMutationContext(), {
            id: request.id,
            claim: {
                claimId: request.claimId,
                ownerSessionId: request.ownerSessionId,
                ownerRuntimeId: request.ownerRuntimeId,
                leaseMs,
            },
        });
        if (!claimed)
            throw new Error(`Task #${request.id} is not claimable`);
        return {
            task: claimed.result.entry,
            claim: claimed.result.claim,
            takenOver: claimed.result.takenOver,
            renewed: claimed.result.renewed,
        };
    }, settledRpcOpts);
    handleRpc(pi.events, TASKS_RPC.heartbeat, (request) => {
        const leaseMs = request.leaseMs;
        if (!request.id || !request.claimId || typeof leaseMs !== "number" || !Number.isSafeInteger(leaseMs)
            || leaseMs < MIN_TASK_LEASE_MS || leaseMs > MAX_TASK_LEASE_MS) {
            throw new Error("id, claimId, and leaseMs between 60000 and 3600000 are required");
        }
        const result = heartbeatTask(requireMutationContext(), {
            id: request.id,
            claimId: request.claimId,
            leaseMs,
        });
        if (!result.applied)
            throw new Error(taskMutationRejectionMessage(request.id, result));
        return { task: result.entry };
    }, settledRpcOpts);
}
